const item = $input.first().json;

const raw = item['OpenAPI or Swagger Spec (JSON)'] || '';
const frameworks = item['Target Frameworks'] || '';
const baseUrl = (item['Base URL (optional)'] || '').trim();

let valid = true;
let error = '';
let spec = null;

if (!raw || String(raw).trim().length === 0) {
  valid = false;
  error = 'No specification was provided. Please paste a valid OpenAPI/Swagger JSON document.';
}

if (valid) {
  try {
    spec = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    valid = false;
    error = 'The specification is not valid JSON: ' + e.message;
  }
}

if (valid && (!spec || (!spec.openapi && !spec.swagger))) {
  valid = false;
  error = 'Missing "openapi" or "swagger" version field. This does not look like an OpenAPI/Swagger document.';
}

if (valid && (!spec.paths || typeof spec.paths !== 'object')) {
  valid = false;
  error = 'No "paths" object found in the specification.';
}

const endpoints = [];
const httpMethods = ['get', 'post', 'put', 'patch', 'delete', 'head', 'options'];
if (valid) {
  for (const path of Object.keys(spec.paths)) {
    const ops = spec.paths[path] || {};
    for (const method of Object.keys(ops)) {
      if (httpMethods.includes(method.toLowerCase())) {
        const op = ops[method] || {};
        endpoints.push({ method: method.toUpperCase(), path: path, summary: op.summary || op.description || '', operationId: op.operationId || '' });
      }
    }
  }
  if (endpoints.length === 0) {
    valid = false;
    error = 'No valid HTTP operations were found under "paths".';
  }
}

return [{ json: { valid, error, endpoints, endpointCount: endpoints.length, frameworks, baseUrl, specTitle: (spec && spec.info && spec.info.title) || 'API', specVersion: (spec && spec.info && spec.info.version) || 'n/a' } }];

const ai = $input.first().json;

let content;
try {
  content = ai.output[0].content[0].text;
} catch (e) {
  content = ai.text || ai;
}

let generated;
if (content && typeof content === 'object') {
  generated = content;
} else {
  const str = typeof content === 'string' ? content : JSON.stringify(content);
  try {
    generated = JSON.parse(str);
  } catch (e) {
    generated = { summary: 'Raw model output (could not parse as JSON).', raw: str };
  }
}

const meta = $('Validate & Parse Spec').first().json;

return [{ json: { status: 'success', api: meta.specTitle, version: meta.specVersion, endpointCount: meta.endpointCount, frameworks: meta.frameworks, endpoints: meta.endpoints, tests: generated, generatedAt: new Date().toISOString() } }];
